/* From Uiverse.io by alexruix - Tags: gradient, card, modern, clean */
.__UIV_SCOPE__ .card {
  height: 254px;
  width: 190px;
  position: relative;
  transition: all 0.4s cubic-bezier(0.645, 0.045, 0.355, 1);
  border-radius: 16px;
  box-shadow: 0 0 20px 8px #d0d0d0;
  overflow: hidden;
}

 /*Image*/
.__UIV_SCOPE__ .card-image {
  height: 100%;
  width: 100%;
  position: absolute;
  transition: all 1s cubic-bezier(0.645, 0.045, 0.355, 1);
  background: #0a3394;
  background: linear-gradient(to top, #0a3394, #4286f4);
}

/*Description */
.__UIV_SCOPE__ .card-description {
  display: flex;
  position: absolute;
  gap: .5em;
  flex-direction: column;
  background-color: #f5f5f5;
  color: #212121;
  height: 70%;
  bottom: 0;
  border-radius: 16px;
  transition: all 1s cubic-bezier(0.645, 0.045, 0.355, 1);
  padding: 1rem;
}

/*Text*/
.__UIV_SCOPE__ .text-title {
  font-size: 1.3rem;
  font-weight: 700;
}

.__UIV_SCOPE__ .text-body {
  font-size: 1rem;
  line-height: 130%;
}


/* Hover states */
.__UIV_SCOPE__ .card:hover .card-description {
  transform: translateY(100%);
}
